    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else {
        this.i = save
        return parts
      }
    }
  }
  basic() {
    this.i++
    let out = ''
    for (;;) {
      const c = this.c
      if (c === undefined) fail('unterminated string')
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        const e = this.s[this.i + 1]
