  let path = basePath
  for (const k of keys.slice(0, -1)) [cur, path] = descend(cur, path, k)
  const last = keys[keys.length - 1]
  if (cur.map.has(last)) fail(`key ${show(path.concat(last))} is defined twice`)
  cur.map.set(last, value)
