export function parseDocument(lines) {
  const root = newTable()
  let cur = root
  let curPath = []
  lines.forEach((line, idx) => {
    try {
      let k = 0
      while (isWs(line[k])) k++
      if (k === line.length || line[k] === '#' || line[k] === ';') return
      const p = new LineParser(line)
      if (line[0] === '[') {
        const aot = line[1] === '['
        p.i = aot ? 2 : 1
