        const keys = p.dotted()
        p.ws()
        for (let n = aot ? 2 : 1; n > 0; n--) {
          if (p.c !== ']') fail('unterminated table header')
          p.i++
        }
        p.ws()
        if (!p.atEnd()) fail('trailing text after a table header')
        let t = root
        let path = []
        for (const key of keys.slice(0, -1)) [t, path] = descend(t, path, key)
        const last = keys[keys.length - 1]
        const full = path.concat(last)
        const ex = t.map.get(last)
        if (aot) {
          if (ex === undefined) {
            const fresh = newTable()
            t.map.set(last, { kind: 'array', items: [fresh], aot: true })
            cur = fresh
          } else if (ex.kind === 'array' && ex.aot) {
            const fresh = newTable()
            ex.items.push(fresh)
            cur = fresh
          } else fail(show(full) + ' is not an array of tables')
        } else if (ex === undefined) {
          const nt = newTable()
          nt.headerDefined = true
          t.map.set(last, nt)
          cur = nt
        } else if (ex.kind === 'table') {
          if (ex.headerDefined) fail(`table ${show(full)} is defined twice`)
          ex.headerDefined = true
          cur = ex
        } else fail(show(full) + ' is not a table')
        curPath = full
        return
      }
      const keys = p.dotted()
      p.ws()
      if (p.c !== '=') fail('expected key = value')
      p.i++
      const v = p.value(curPath.concat(keys))
      p.ws()
      if (!p.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, keys, v)
    } catch (e) {
      if (e && e.isConfigError) e.line = idx + 1
      throw e
    }
  })
  return root
}
